/**
 * A record describing a changeset file that was hidden by {@link hideReleased}.
 * `id` is the changeset basename (without the `.md` extension). The remaining
 * fields carry the absolute paths needed to restore or delete the file later.
 */
export interface HiddenChangeset {
  id: string
  mdPath: string
  releasedPath: string
  [key: string]: unknown
}

/**
 * Converts a git branch name to a safe filename by replacing every
 * forward-slash with a dash and appending the `.txt` extension.
 */
export function branchToFilename (branch: string): string {
  return `${branch.replaceAll('/', '-')}.txt`
}

/**
 * Reads all `.txt` files in `dir` and collects their non-empty, non-comment
 * lines as changeset IDs, merged and deduplicated across files. Returns an
 * empty Set when `dir` does not exist.
 */
export function readReleased (dir: string): Set<string> {
  const released = new Set<string>()
  if (!fs.existsSync(dir)) return released
  for (const entry of fs.readdirSync(dir)) {
    if (path.extname(entry) !== '.txt') continue
    const content = fs.readFileSync(path.join(dir, entry), 'utf8')
    for (const rawLine of content.split('\n')) {
      const line = rawLine.trim()
      if (line === '' || line.startsWith('#')) continue
      released.add(line)
    }
  }
  return released
}

/**
 * Appends `ids` to the file named `branchToFilename(branch)` inside `dir`,
 * deduplicating against IDs already present in that file. Writes the merged,
 * sorted list back (one ID per line, trailing newline). Creates `dir` and any
 * missing parents. A no-op when `ids` is empty — no file is created.
 */
export function appendReleased (dir: string, branch: string, ids: string[]): void {
  if (ids.length === 0) return
  fs.mkdirSync(dir, { recursive: true })
  const filePath = path.join(dir, branchToFilename(branch))
  const merged = new Set<string>()
  if (fs.existsSync(filePath)) {
    for (const rawLine of fs.readFileSync(filePath, 'utf8').split('\n')) {
      const line = rawLine.trim()
      if (line === '' || line.startsWith('#')) continue
      merged.add(line)
    }
  }
  for (const id of ids) {
    merged.add(id)
  }
  const sorted = Array.from(merged).sort()
  fs.writeFileSync(filePath, `${sorted.join('\n')}\n`)
}

/**
 * For each `.md` file in `dir` whose basename is contained in `releasedIds`,
 * renames `<id>.md` to `<id>.md.released`. Returns a record per hidden file.
 * IDs without a matching `.md` file are silently skipped. If any rename fails,
 * all completed renames are rolled back and the original error is re-thrown.
 */
export function hideReleased (dir: string, releasedIds: Set<string>): HiddenChangeset[] {
  const hidden: HiddenChangeset[] = []
  try {
    for (const id of releasedIds) {
      const mdPath = path.join(dir, `${id}.md`)
      if (!fs.existsSync(mdPath)) continue
      const releasedPath = `${mdPath}.released`
      fs.renameSync(mdPath, releasedPath)
      hidden.push({ id, mdPath, releasedPath })
    }
  } catch (err) {
    for (const entry of hidden) {
      fs.renameSync(entry.releasedPath, entry.mdPath)
    }
    throw err
  }
  return hidden
}

/**
 * Renames each `.md.released` file referenced in `hidden` back to its original
 * `.md` name. Accepts the array returned by {@link hideReleased}.
 */
export function restoreHidden (hidden: HiddenChangeset[]): void {
  for (const entry of hidden) {
    fs.renameSync(entry.releasedPath, entry.mdPath)
  }
}

/**
 * Permanently deletes each `.md.released` file referenced in `hidden`.
 * Accepts the array returned by {@link hideReleased}.
 */
export function deleteHidden (hidden: HiddenChangeset[]): void {
  for (const entry of hidden) {
    fs.rmSync(entry.releasedPath, { force: true })
  }
}

/**
 * Returns a sorted array of changeset IDs by listing `.md` files in `dir` and
 * stripping the `.md` extension. Excludes `README.md` and ignores non-`.md`
 * files.
 */
export function listChangesetIds (dir: string): string[] {
  const ids: string[] = []
  for (const entry of fs.readdirSync(dir)) {
    if (path.extname(entry) !== '.md') continue
    if (entry === 'README.md') continue
    ids.push(entry.slice(0, -'.md'.length))
  }
  return ids.sort()
}
